mapper.select:
SELECT c.chatroom_id, c.name, c.description, COALESCE(mc.member_count, 0) AS member_count, COALESCE(msg.message_count, 0) AS message_count, c.max_members, c.status, c.is_private, c.created_at, c.updated_at FROM chatrooms c LEFT JOIN ( SELECT chatroom_id, COUNT(*) AS member_count FROM chatroom_members GROUP BY chatroom_id ) mc ON c.chatroom_id = mc.chatroom_id LEFT JOIN ( SELECT chatroom_id, COUNT(*) AS message_count FROM chatroom_messages GROUP BY chatroom_id ) msg ON c.chatroom_id = msg.chatroom_id
WHERE c.name LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE chatrooms
name = #{name}, description = #{description}, max_members = #{maxMembers}, is_private = #{isPrivate}, status = #{status}, updated_at = #{updatedAt}
WHERE chatroom_id = #{chatroomId}

mapper.select:
SELECT cm.user_id, u.username, COALESCE(cm.nickname, u.username) AS nickname, u.avatar_url, cm.role, cm.joined_at, cm.last_active_time, COALESCE(msg.message_count, 0) AS message_count, cm.muted_until FROM chatroom_members cm JOIN users u ON cm.user_id = u.user_id LEFT JOIN ( SELECT chatroom_id, user_id, COUNT(*) AS message_count FROM chatroom_messages GROUP BY chatroom_id, user_id ) msg ON cm.chatroom_id = msg.chatroom_id AND cm.user_id = msg.user_id WHERE cm.chatroom_id = #{chatroomId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY cm.role DESC, cm.joined_at ASC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE chatroom_members
SET role = #{role}
WHERE chatroom_id = #{chatroomId} AND user_id = #{userId}

mapper.select:
SELECT m.message_id, m.chatroom_id, m.user_id, u.username, m.content, m.is_recalled, m.is_pinned, m.created_at
FROM chatroom_messages m
JOIN users u ON m.user_id = u.user_id
WHERE m.chatroom_id = #{chatroomId}
ORDER BY m.created_at ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE chatroom_members
SET last_active_time = NOW(), message_count = message_count + 1
WHERE chatroom_id = #{chatroomId} AND user_id = #{userId}

UPDATE chatroom_members
SET muted_until = #{mutedUntil}
WHERE chatroom_id = #{chatroomId} AND user_id = #{userId}

mapper.select:
SELECT DATE(cm.created_at) AS date, COUNT(cm.message_id) AS messageCount, COUNT(DISTINCT cm.user_id) AS activeMembers, COUNT(DISTINCT CASE WHEN DATE(cm.created_at) = DATE(cm.created_at) THEN cm.user_id END) AS newMembers FROM chatroom_messages cm WHERE cm.chatroom_id = #{chatroomId}
AND DATE(cm.created_at) >= #{startDate}
AND DATE(cm.created_at) <= #{endDate}
GROUP BY DATE(cm.created_at) ORDER BY date DESC
